from math import gcd
class Solution:
    def maxGcdSum(self, nums, k):
        n = len(nums)
        best = 0
        for i in range(n):
            g = 0
            s = 0
            for j in range(i, -1, -1):
                g = gcd(g, nums[j])
                s += nums[j]
                if i - j + 1 >= k:
                    best = max(best, g * s)
        return best

