from math import gcd
class Solution:
    def maxGcdSum(self, nums, k):
        n = len(nums)
        P = [0] * (n + 1)
        for i, x in enumerate(nums):
            P[i + 1] = P[i] + x
        segs = []
        best = 0
        for i, x in enumerate(nums):
            ns = []
            for g, l in segs:
                ng = gcd(g, x)
                if not ns or ns[-1][0] != ng:
                    ns.append([ng, l])
            if not ns or ns[-1][0] != x:
                ns.append([x, i])
            segs = ns
            for g, l in segs:
                st = max(l, i - k + 1)
                best = max(best, g * (P[i + 1] - P[st]))
        return best

