        vector<long long> P(n + 1, 0);
        for (int i = 0; i < n; i++) P[i + 1] = P[i] + nums[i];
        vector<pair<long long,int>> segs;
        long long best = 0;
        for (int i = 0; i < n; i++) {
            vector<pair<long long,int>> ns;
            for (auto& [g, l] : segs) {
                long long ng = std::gcd(g, (long long)nums[i]);
                if (ns.empty() || ns.back().first != ng) ns.push_back({ng, l});
            }
            if (ns.empty() || ns.back().first != nums[i]) ns.push_back({nums[i], i});
            segs = move(ns);
            for (auto& [g, l] : segs) {
                int st = max(l, i - k + 1);
                best = max(best, g * (P[i + 1] - P[st]));
            }
        }
        return best;
    }
};

