class Solution {
    public long maxGcdSum(int[] nums, int k) {
        int n = nums.length;
        long[] P = new long[n + 1];
        for (int i = 0; i < n; i++) P[i + 1] = P[i] + nums[i];
        List<long[]> segs = new ArrayList<>();
        long best = 0;
        for (int i = 0; i < n; i++) {
            List<long[]> ns = new ArrayList<>();
            for (long[] s : segs) {
                long ng = gcd(s[0], nums[i]);
                if (ns.isEmpty() || ns.get(ns.size() - 1)[0] != ng) ns.add(new long[]{ng, s[1]});
            }
            if (ns.isEmpty() || ns.get(ns.size() - 1)[0] != nums[i]) ns.add(new long[]{nums[i], i});
            segs = ns;
            for (long[] s : segs) {
                int st = (int) Math.max(s[1], i - k + 1);
                best = Math.max(best, s[0] * (P[i + 1] - P[st]));
            }
        }
        return best;
    }
    private long gcd(long a, long b) { return b == 0 ? a : gcd(b, a % b); }
}

