var maxGcdSum = function(nums, k) {
    const gcd = (a, b) => b === 0n ? a : gcd(b, a % b);
    const n = nums.length;
    const P = new Array(n + 1).fill(0n);
    for (let i = 0; i < n; i++) P[i + 1] = P[i] + BigInt(nums[i]);
    let segs = [];
    let best = 0n;
    for (let i = 0; i < n; i++) {
        const x = BigInt(nums[i]);
        const ns = [];
        for (const [g, l] of segs) {
            const ng = gcd(g, x);
            if (ns.length === 0 || ns[ns.length - 1][0] !== ng) ns.push([ng, l]);
        }
        if (ns.length === 0 || ns[ns.length - 1][0] !== x) ns.push([x, i]);
        segs = ns;
        for (const [g, l] of segs) {
            const st = Math.max(l, i - k + 1);
            const cand = g * (P[i + 1] - P[st]);
            if (cand > best) best = cand;
        }
    }
    return Number(best);
};
